package com.paybridge.bkash;
import static com.github.tomakehurst.wiremock.client.WireMock.*;import static org.junit.jupiter.api.Assertions.*;import com.github.tomakehurst.wiremock.junit5.WireMockExtension;import com.paybridge.core.model.*;import java.net.URI;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.RegisterExtension;
class BkashPaymentGatewayTest {@RegisterExtension static WireMockExtension wm=WireMockExtension.newInstance().options(com.github.tomakehurst.wiremock.core.WireMockConfiguration.wireMockConfig().dynamicPort()).build();@Test void creates_hosted_checkout_after_authentication(){wm.stubFor(post("/tokenized/checkout/token/grant").willReturn(okJson("{\"id_token\":\"token\",\"expires_in\":3600}")));wm.stubFor(post("/tokenized/checkout/create").withHeader("Authorization",equalTo("token")).withHeader("X-Idempotency-Key",equalTo("order1")).willReturn(okJson("{\"paymentID\":\"P1\",\"bkashURL\":\"https://checkout.example/P1\",\"transactionStatus\":\"Initiated\"}")));var g=new BkashPaymentGateway(new BkashConfiguration("key","secret","user","pass",URI.create(wm.baseUrl()),URI.create("https://merchant.example/callback")));var p=g.createPayment(new PaymentRequest(Money.of("20","BDT"),"invoice-1",null,null,new IdempotencyKey("order1"),null));assertEquals("P1",p.reference().value());assertEquals(PaymentStatus.REQUIRES_ACTION,p.status());}}
